/**
 * Bounded-concurrency map, in input order. Local rather than
 * `@anysphere/utils`: this published package cannot depend on monorepo
 * internals.
 */
export async function mapBounded(items, max, run) {
    const out = new Array(items.length);
    let nextIndex = 0;
    const workers = Array.from({ length: Math.min(max, items.length) }, async () => {
        for (;;) {
            const index = nextIndex;
            nextIndex += 1;
            if (index >= items.length) {
                return;
            }
            out[index] = await run(items[index]);
        }
    });
    await Promise.all(workers);
    return out;
}
